# One entry per card (v2 – sheet received 5 Nov). codes = Diwan item numbers on the card.
# Cards are split wherever flavours carry different prices.
# per="200"/"500": show the sheet's "Price In 200G" column (labneh = per 500 g) instead of the kg price.
KG = ("1 كغ", "1 Kg")
G200 = ("200 غ", "200 g")
G400 = ("400 غ", "400 g")
PC = ("1 حبّة", "1 pc")
# dup=n: repeat the pack photo n times back to back (multipacks). from_=True: show "starting from" the lowest price.
# save_txt: fixed saving badge text (e.g. Chtoura frozen "up to 20%").
UP20 = "حتى 20%"
# short_ar: shorter Arabic name for carousel/16:9 slides, where cards sit 3-4 per row (flyer keeps "ar").
def C(cat, codes, ar, en, unit, img, var=None, per=None, dup=1, from_=False, save_txt=None, short_ar=None):
    return dict(cat=cat, codes=codes.split(), ar=ar, en=en, u_ar=unit[0], u_en=unit[1],
                img=img if isinstance(img, list) or img is None else [img], var_ar=var, per=per,
                dup=dup, from_=from_, save_txt=save_txt, short_ar=short_ar)

